Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; width: 100%; height: 100%; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 100;
        const FINISH_LINE_Z = -40;
        const CAR_SPACING = 2;
        const RACE_DURATION = 8; // Seconds for one full loop

        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky Blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 120);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 200);
        camera.position.set(0, 12, 40);
        camera.lookAt(0, 0, -20);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(10, 20, 20);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        dirLight.shadow.camera.near = 0.5;
        dirLight.shadow.camera.far = 50;
        dirLight.shadow.camera.left = -20;
        dirLight.shadow.camera.right = 20;
        dirLight.shadow.camera.top = 20;
        dirLight.shadow.camera.bottom = -20;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(200, 200);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x33aa33, roughness: 1 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Track
        const trackGeo = new THREE.PlaneGeometry(10, 200);
        const trackMat = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.8 });
        const track = new THREE.Mesh(trackGeo, trackMat);
        track.rotation.x = -Math.PI / 2;
        track.position.y = 0.01; // Slightly above ground to prevent z-fighting
        track.receiveShadow = true;
        scene.add(track);

        // Finish Line
        const finishGeo = new THREE.PlaneGeometry(10, 2);
        // Create a simple checkerboard texture using canvas
        const canvas = document.createElement('canvas');
        canvas.width = 128; canvas.height = 128;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = 'white'; ctx.fillRect(0,0,128,128);
        ctx.fillStyle = 'black';
        for(let i=0; i<8; i++) { for(let j=0; j<8; j++) { if((i+j)%2===0) ctx.fillRect(i*16, j*16, 16, 16); } }
        const finishTex = new THREE.CanvasTexture(canvas);
        finishTex.rotation = -Math.PI/2;
        finishTex.wrapS = THREE.RepeatWrapping;
        finishTex.wrapT = THREE.RepeatWrapping;
        finishTex.repeat.set(1, 1);

        const finishMat = new THREE.MeshBasicMaterial({ map: finishTex });
        const finishLine = new THREE.Mesh(finishGeo, finishMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.02, FINISH_LINE_Z);
        finishLine.receiveShadow = true;
        scene.add(finishLine);

        // --- Car Construction ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(1.8, 0.6, 3.5);
            const chassisMat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.2, metalness: 0.5 });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = 0.6;
            chassis.castShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(1.4, 0.5, 1.8);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.1, metalness: 0.8 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.set(0, 1.1, -0.2);
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.4, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
            const wheelPositions = [
                { x: -1, z: 1.2 }, { x: 1, z: 1.2 },
                { x: -1, z: -1.2 }, { x: 1, z: -1.2 }
            ];

            wheelPositions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, 0.4, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            return carGroup;
        }

        const blueCar = createCar(0x0000FF);
        const redCar = createCar(0xFF0000);

        // Position cars
        blueCar.position.set(-CAR_SPACING/2, 0, 40);
        redCar.position.set(CAR_SPACING/2, 0, 40);

        scene.add(blueCar);
        scene.add(redCar);

        // --- Animation Logic ---
        let raceTime = 0;
        let isRedWinning = false;

        function getSpeed(progress) {
            // Blue: Fast start, slows down near end
            // Red: Slow start, massive acceleration near end

            // Blue curve: High at 0, drops
            let blueBase = 1.0;
            let blueMod = Math.sin(progress * Math.PI) * 0.5; // Slow in middle? No, let's keep it steady then brake
            // Better Blue: Constant high speed, then brakes slightly
            if (progress > 0.8) blueBase = 0.8;

            // Red curve: Slow start, exponential acceleration
            let redBase = 0.6;
            if (progress > 0.5) {
                let accel = (progress - 0.5) * 2;
                redBase = 0.6 + accel * 2.5; // Massive boost
            }

            return { blue: blueBase, red: redBase };
        }

        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const delta = clock.getDelta();

            // Reset logic
            if (redCar.position.z < FINISH_LINE_Z - 10) {
                raceTime = 0;
                isRedWinning = false;
                blueCar.position.z = 40;
                redCar.position.z = 40;
            } else {
                raceTime += delta;

                // Progress 0 to 1 (Start to Finish)
                const totalDist = 40 - FINISH_LINE_Z;
                let blueZ = 40;
                let redZ = 40;

                // Simple integration for position based on normalized time
                // We calculate distance traveled based on speed curves
                const progressTime = raceTime / RACE_DURATION;

                if (progressTime <= 1) {
                    // Calculate positions using a simplified integral approximation of the speed curves
                    // Blue travels distance D
                    let blueDist = 0;
                    // Red travels distance D
                    let redDist = 0;

                    // Using a lookup approach for smoother animation control
                    // Blue: Linear mostly, slight ease out
                    blueDist = progressTime * (1 - 0.1 * Math.pow(progressTime, 2)); 

                    // Red: Ease in heavily
                    // 0 to 0.5: slow linear
                    // 0.5 to 1: fast ease out
                    if (progressTime < 0.5) {
                        redDist = progressTime * 0.6;
                    } else {
                        const t = (progressTime - 0.5) * 2;
                        redDist = 0.3 + t * t * 0.7; // 0.3 is distance covered in first half
                    }

                    blueZ = 40 - (blueDist * totalDist);
                    redZ = 40 - (redDist * totalDist);

                    // Determine winner state for camera shake/effects if needed
                    if (redZ < blueZ && !isRedWinning && progressTime > 0.5) {
                        isRedWinning = true;
                    }
                }

                blueCar.position.z = blueZ;
                redCar.position.z = redZ;

                // Camera Follow
                // Average position
                const midZ = (blueZ + redZ) / 2;
                const minZ = Math.min(blueZ, redZ);

                // Camera tracks slightly ahead of the leader
                const targetZ = minZ - 15;

                // Smooth camera movement
                camera.position.z += (targetZ - camera.position.z) * 0.1;
                camera.lookAt(0, 0, minZ - 10);

                // Light follows camera to keep shadows sharp on cars
                dirLight.position.z = camera.position.z + 20;
                dirLight.target.position.z = camera.position.z - 10;
                dirLight.target.updateMatrixWorld();
            }

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
